template:
use std::thread;

fn sum_halves(numbers: &[i32]) -> i32 {
    let mid = numbers.len() / 2;
    let (left, right) = numbers.split_at(mid);

    ⟦slot1⟧(|s| {
        let h1 = ⟦slot2⟧(|| left.iter().sum::<i32>());
        let h2 = s.spawn(|| right.iter().sum::<i32>());
        h1.join().unwrap() + h2.join().unwrap()
    })
}

fn main() {
    let nums = vec![1, 2, 3, 4, 5, 6];
    println!("{}", sum_halves(&nums));
}

tests:
#[test]
fn calculates_sum() {
    let nums = vec![1, 2, 3, 4, 5, 6];
    assert_eq!(sum_halves(&nums), 21);
}
